/* Task: recursion — merge sort (paper's merge-sort benchmark, 121 LOC,
 * recursion -> stack conversion, stack-size sensitivity 1024 vs 2048).
 * Deliberately HLS-incompatible:
 *  - merge_sort() is recursive (two self-calls)
 *  - merge() heap-allocates its temp buffers L/R with malloc/free
 *  - kernel and main take raw pointers (int *a)
 * Behaviour: sort the array, print a position-weighted checksum.
 * Test inputs are generated by the harness (n, seed) sweep, not baked in.
 */
#include <stdio.h>
#include <stdlib.h>

void merge(int *a, int l, int m, int r) {
    int n1 = m - l + 1;
    int n2 = r - m;
    int *L = (int *)malloc(n1 * sizeof(int));
    int *R = (int *)malloc(n2 * sizeof(int));
    int i, j, k;
    for (i = 0; i < n1; i++) {
        L[i] = a[l + i];
    }
    for (j = 0; j < n2; j++) {
        R[j] = a[m + 1 + j];
    }
    i = 0;
    j = 0;
    k = l;
    while (i < n1 && j < n2) {
        if (L[i] <= R[j]) {
            a[k++] = L[i++];
        } else {
            a[k++] = R[j++];
        }
    }
    while (i < n1) {
        a[k++] = L[i++];
    }
    while (j < n2) {
        a[k++] = R[j++];
    }
    free(L);
    free(R);
}

void merge_sort(int *a, int l, int r) {
    if (l < r) {
        int m = l + (r - l) / 2;
        merge_sort(a, l, m);
        merge_sort(a, m + 1, r);
        merge(a, l, m, r);
    }
}

static unsigned int rng_state = 1;
static int next_rand_int(void) {
    rng_state = rng_state * 1103515245u + 12345u;
    return (int)((rng_state >> 16) & 0xFF);
}

int main(int argc, char **argv) {
    int n = 64;
    if (argc > 1) {
        n = atoi(argv[1]);
    }
    if (argc > 2) {
        rng_state = (unsigned int)atoi(argv[2]);
    }
    int *a = (int *)malloc(n * sizeof(int));
    int i;
    for (i = 0; i < n; i++) {
        a[i] = next_rand_int();
    }
    merge_sort(a, 0, n - 1);
    double checksum = 0.0;
    for (i = 0; i < n; i++) {
        checksum += (double)a[i] * (i + 1);
    }
    printf("checksum=%.6f\n", checksum);
    free(a);
    return 0;
}
